/* space-data.js — entries of the Space Atlas (space-atlas.html). */
(function () {
  window.SPACE_CATS = {
    astro: ['Ancient & early astronomy', '#8a6a4a', '🌌'],
    discovery: ['Great discoveries', '#8a6cc0', '💫'],
    scope: ['Telescopes & observatories', '#2a8fa3', '🔭'],
    rocket: ['Rockets', '#c0392b', '🚀'],
    sat: ['Satellites', '#4f7598', '🛰️'],
    human: ['Human spaceflight', '#e67e22', '👩‍🚀'],
    moon: ['The Moon', '#7f8c8d', '🌕'],
    planet: ['Planets & probes', '#c9922a', '🪐'],
    station: ['Space stations', '#2e7d32', '🏠']
  };
  window.SPACE_ERAS = [
    { n: 'Ancient sky-watchers', to: 1500, range: 'before 1500', intro: 'People everywhere watched the Sun, Moon, planets and stars to keep calendars, steer ships and tell stories. Astronomers in Babylon, Greece, India, the Islamic world, China and the Maya made precise records.' },
    { n: 'The scientific revolution', to: 1800, range: '1500 – 1799', intro: 'Copernicus put the Sun at the centre, Galileo turned a telescope to the sky, Kepler found the laws of the planets and Newton explained them with gravity.' },
    { n: 'The age of big telescopes', to: 1946, range: '1800 – 1945', intro: 'Bigger telescopes and spectroscopes found new planets and galaxies, showed what stars are made of and that the universe is expanding. Rocket pioneers dreamed of space travel.' },
    { n: 'The space race', to: 1977, range: '1946 – 1976', intro: 'The USA and the Soviet Union raced from the first satellite to people on the Moon, while probes reached Venus and Mars.' },
    { n: 'Shuttles, stations & great observatories', to: 2000, range: '1977 – 1999', intro: 'Voyager toured the outer planets, the Space Shuttle flew, the Hubble Space Telescope opened its eyes and the International Space Station began.' },
    { n: 'The new space age', to: 99999, range: '2000 – today', intro: 'Rovers on Mars, reusable rockets, China and India on the Moon, the James Webb telescope, images of black holes and missions to asteroids and the Sun.' }
  ];
  window.SPACE = [
    // ---------------- ancient
    { id: 'stonehenge', n: 'Stonehenge', c: 'astro', y: -2500, d: 'c. 2500 BCE', r: 'England', w: 'Neolithic Britons', s: 'A ring of giant stones lined up with the sunrise at midsummer and the sunset at midwinter.', how: 'The main axis points to where the Sun rises on the longest day and sets on the shortest.', impact: 'Shows that people tracked the Sun’s yearly cycle thousands of years ago.', f: 'Some of its bluestones were brought about 225 km from Wales.', p: ['stonehenge'], x: ['nebra-disc'] },
    { id: 'nebra-disc', n: 'Nebra sky disc', c: 'astro', y: -1600, d: 'c. 1600 BCE', r: 'Germany', w: 'Bronze Age people', s: 'A bronze disc with gold shapes of the Sun or full Moon, a crescent Moon and stars — the oldest known picture of the sky.', how: 'Gold arcs on the edges mark the range of sunrise and sunset points through the year.', impact: 'It may have helped farmers keep a calendar.', f: 'It was dug up illegally by treasure hunters and recovered by police in 1999.', p: ['moon'], x: ['stonehenge', 'babylonian-astronomy'] },
    { id: 'babylonian-astronomy', n: 'Babylonian astronomy', c: 'astro', y: -700, d: 'c. 700 BCE', r: 'Babylon (Iraq)', w: 'Babylonian astronomer-priests', s: 'Clay tablets recorded the sky night after night for centuries, letting astronomers predict eclipses.', how: 'Long records revealed repeating cycles, such as the 18-year saros cycle of eclipses.', impact: 'The 360 degrees of a circle and 60-minute hour come from Babylonian maths.', f: 'They used mathematical methods to track Jupiter that were once thought to have been invented in medieval Europe.', p: ['med', { i: 'tablet' }], x: ['hipparchus'] },
    { id: 'aristarchus', n: 'Aristarchus: the Sun at the centre', c: 'astro', y: -270, d: 'c. 270 BCE', r: 'Samos, Greece', w: 'Aristarchus of Samos', s: 'The first known person to say the Earth goes round the Sun.', how: 'He estimated that the Sun is much bigger than the Earth, so it made sense for Earth to move.', impact: 'Few believed him; the idea returned with Copernicus 1,800 years later.', f: 'Copernicus mentioned Aristarchus in an early draft of his book.', p: ['orbit'], x: ['copernicus', 'eratosthenes'] },
    { id: 'eratosthenes', n: 'Eratosthenes measures the Earth', c: 'astro', y: -240, d: 'c. 240 BCE', r: 'Alexandria, Egypt', w: 'Eratosthenes', s: 'Using shadows in two cities, he worked out the Earth’s size with remarkable accuracy.', how: 'At noon in Syene the Sun was straight overhead; in Alexandria it cast a shadow of about 7°, one fiftieth of a circle.', impact: 'Educated people knew the Earth was round long before Columbus.', f: 'His answer was probably within a few percent of the true value.', p: ['earth'], x: ['aristarchus', 'ptolemy'] },
    { id: 'hipparchus', n: 'Hipparchus’s star catalogue', c: 'astro', y: -130, d: 'c. 130 BCE', r: 'Rhodes, Greece', w: 'Hipparchus', s: 'He catalogued about 850 stars by position and brightness and discovered the slow wobble of Earth’s axis.', how: 'Comparing his star positions with older records showed they had all shifted slightly (precession).', impact: 'His magnitude scale for star brightness is still used.', f: 'He may have been inspired by a new star that appeared in the sky.', p: ['galaxy'], x: ['babylonian-astronomy', 'ptolemy'] },
    { id: 'ptolemy', n: 'Ptolemy’s Almagest', c: 'astro', y: 150, d: 'c. 150 CE', r: 'Alexandria, Egypt', w: 'Claudius Ptolemy', s: 'A great astronomy book with an Earth-centred model that predicted planet positions well for 1,400 years.', how: 'Planets moved on small circles (epicycles) riding on bigger circles around Earth.', impact: 'Kept alive and improved by Islamic astronomers; replaced by Copernicus and Kepler.', f: 'Almagest comes from the Arabic name, meaning “the greatest”.', p: ['orbit', { earth: 1 }], x: ['copernicus', 'al-sufi'] },
    { id: 'aryabhata', n: 'Aryabhata', c: 'astro', y: 499, d: '499', r: 'India', w: 'Aryabhata', s: 'An Indian mathematician who said the Earth spins on its axis, making the stars seem to move.', how: 'He compared it to a person in a boat seeing the shore move backwards.', impact: 'He explained eclipses as shadows and calculated pi to four decimal places.', f: 'India’s first satellite (1975) was named Aryabhata.', p: ['earth'], x: ['ptolemy'] },
    { id: 'astrolabe', n: 'Astrolabe', c: 'scope', y: 800, d: 'perfected c. 8th–9th century', r: 'Greek world, then the Islamic world', w: 'Greek and Islamic astronomers, including Mariam al-Ijliya', s: 'A brass instrument that models the sky, used to tell time, find directions and measure star heights.', how: 'Rotating plates show the sky above a particular latitude; a sighting rule measures star angles.', impact: 'Used by astronomers and travellers for 1,000 years.', f: 'Mariam al-Ijliya of Aleppo was a famous 10th-century astrolabe maker.', p: ['astrolabe'], x: ['al-sufi'] },
    { id: 'al-sufi', n: 'Al-Sufi’s Book of Fixed Stars', c: 'astro', y: 964, d: '964', r: 'Persia', w: 'Abd al-Rahman al-Sufi', s: 'A beautiful star atlas with the first recorded description of the Andromeda Galaxy, which he called a “little cloud”.', how: 'He checked Ptolemy’s stars by observation and added Arabic star names.', impact: 'Many star names we use, like Aldebaran and Betelgeuse, come from Arabic.', f: 'Andromeda is the most distant thing you can see with the naked eye: about 2.5 million light years away.', p: ['galaxy'], x: ['ptolemy', 'other-galaxies'] },
    { id: 'supernova-1054', n: 'Supernova of 1054', c: 'astro', y: 1054, d: '1054', r: 'China and elsewhere', w: 'Chinese court astronomers', s: 'A “guest star” bright enough to see in daylight for three weeks — an exploding star.', how: 'A dying star blew apart; its remains are the Crab Nebula.', impact: 'In the 1900s astronomers matched the records with the Crab Nebula, proving it was a supernova.', f: 'A pulsar spinning 30 times a second sits at the centre of the Crab Nebula.', p: ['pulsar'], x: ['tycho', 'pulsars'] },
    { id: 'maya-venus', n: 'Maya Venus tables', c: 'astro', y: 1200, d: 'c. 12th century', r: 'Mesoamerica', w: 'Maya astronomers (Dresden Codex)', s: 'Tables predicting the movements of Venus for over a century, accurate to a few hours.', how: 'Long observation of Venus’s 584-day cycle, corrected for small errors.', impact: 'Used to time rituals and wars.', f: 'Only four Maya books survived Spanish burnings; the Dresden Codex is one.', p: ['planet', { color: '#e8d7a0', r: 30 }], x: ['babylonian-astronomy'] },
    { id: 'ulugh-beg', n: 'Ulugh Beg’s observatory', c: 'scope', y: 1424, d: '1424', r: 'Samarkand (Uzbekistan)', w: 'Ulugh Beg', s: 'A huge observatory with a curved stone instrument 40 metres long, used to make a famous star catalogue.', how: 'A giant meridian arc set into a trench measured star positions very precisely.', impact: 'His catalogue of over 1,000 stars was the best since Ptolemy.', f: 'Ulugh Beg was a ruler as well as an astronomer.', p: ['telescope', { type: 'observatory' }], x: ['astrolabe', 'tycho'] },
    // ---------------- scientific revolution
    { id: 'copernicus', n: 'Copernicus: the Sun at the centre', c: 'discovery', y: 1543, d: '1543', r: 'Poland', w: 'Nicolaus Copernicus', s: 'His book put the Sun, not the Earth, at the centre of the planets.', how: 'A Sun-centred model explained why planets sometimes seem to move backwards.', impact: 'It began the scientific revolution. The church later banned it for a time.', f: 'Copernicus is said to have received the first printed copy on the day he died.', p: ['orbit'], x: ['aristarchus', 'galileo', 'kepler'] },
    { id: 'tycho', n: 'Tycho Brahe’s observations', c: 'scope', y: 1572, d: '1572', r: 'Denmark', w: 'Tycho Brahe', s: 'He saw a new star (a supernova) and built observatories to measure the planets more accurately than ever, without a telescope.', how: 'Giant instruments and careful repeat measurements reduced errors.', impact: 'His records let Kepler discover the laws of planetary motion.', f: 'Tycho lost part of his nose in a duel and wore a metal replacement.', p: ['telescope', { type: 'observatory' }], x: ['kepler', 'supernova-1054'] },
    { id: 'galileo', n: 'Galileo’s telescope', c: 'discovery', y: 1610, d: '1610', r: 'Padua, Italy', w: 'Galileo Galilei', s: 'Galileo turned a telescope to the sky and saw moons orbiting Jupiter, mountains on the Moon and phases of Venus.', how: 'His telescope magnified about 20 times.', impact: 'Moons circling Jupiter showed that not everything goes round the Earth.', f: 'He was put under house arrest in 1633 for supporting Copernicus; the church admitted its error in 1992.', p: ['telescope'], x: ['copernicus', 'kepler', ['invention-atlas.html#telescope', 'The telescope']] },
    { id: 'kepler', n: 'Kepler’s laws', c: 'discovery', y: 1609, d: '1609–1619', r: 'Prague and Linz', w: 'Johannes Kepler', s: 'Planets move in ellipses, faster when close to the Sun, following exact mathematical rules.', how: 'Kepler fitted Tycho’s measurements of Mars until only an ellipse worked.', impact: 'Newton later explained Kepler’s laws with gravity.', f: 'Kepler also wrote one of the first science-fiction stories, about a trip to the Moon.', p: ['orbit'], x: ['tycho', 'newton'] },
    { id: 'reflecting-telescope', n: 'Reflecting telescope', c: 'scope', y: 1668, d: '1668', r: 'England', w: 'Isaac Newton', s: 'A telescope that uses a curved mirror instead of a lens to collect light.', how: 'A concave mirror focuses light without the colour fringes lenses produce.', impact: 'Almost all big telescopes today are reflectors.', f: 'Newton’s first reflector was only 15 cm long.', p: ['telescope', { type: 'reflector' }], x: ['newton', 'hubble-telescope'] },
    { id: 'newton', n: 'Newton’s law of gravity', c: 'discovery', y: 1687, d: '1687', r: 'England', w: 'Isaac Newton', s: 'One law of gravity explains both falling apples and the orbits of the Moon and planets.', how: 'Every mass attracts every other mass, weaker with the square of the distance.', impact: 'It let astronomers predict orbits, comets and later spacecraft paths.', f: 'Newton’s Principia was paid for by his friend Edmond Halley.', p: ['orbit', { earth: 1 }], x: ['kepler', 'halley'] },
    { id: 'halley', n: 'Halley’s Comet predicted', c: 'discovery', y: 1705, d: '1705 (prediction); 1758 (return)', r: 'England', w: 'Edmond Halley', s: 'Halley showed that comets seen in 1531, 1607 and 1682 were one comet, and predicted its return.', how: 'He used Newton’s gravity to calculate its orbit of about 76 years.', impact: 'It returned in 1758, after his death — proof that Newton’s laws worked.', f: 'Halley’s Comet appears in the Bayeux Tapestry of 1066.', p: ['comet'], x: ['newton', 'giotto'] },
    { id: 'uranus', n: 'Discovery of Uranus', c: 'discovery', y: 1781, d: '1781', r: 'Bath, England', w: 'William Herschel (with Caroline Herschel)', s: 'The first planet found with a telescope, doubling the size of the known Solar System.', how: 'Herschel noticed a “star” that was a disc and moved against the background.', impact: 'Caroline Herschel became the first woman paid as an astronomer and discovered eight comets.', f: 'Herschel wanted to name it “George’s Star” after King George III.', p: ['planet', { color: '#9fd6df', r: 30 }], x: ['neptune'] },
    // ---------------- big telescopes
    { id: 'spectroscopy', n: 'Spectroscopy: reading starlight', c: 'discovery', y: 1859, d: '1814–1859', r: 'Germany', w: 'Joseph von Fraunhofer; Gustav Kirchhoff and Robert Bunsen', s: 'Splitting starlight into a rainbow reveals dark lines that show what the star is made of.', how: 'Each element absorbs or gives out light at its own exact colours.', impact: 'Astronomers could study the chemistry, temperature and motion of stars.', f: 'Helium was found in the Sun’s spectrum in 1868, before it was found on Earth.', p: ['sun'], x: ['payne', 'expanding-universe'] },
    { id: 'neptune', n: 'Discovery of Neptune', c: 'discovery', y: 1846, d: '1846', r: 'France and Germany', w: 'Urbain Le Verrier; Johann Galle', s: 'A planet found by mathematics: Le Verrier predicted where it should be from wobbles in Uranus’s orbit.', how: 'The pull of an unseen planet was changing Uranus’s path.', impact: 'Galle found Neptune within 1° of the predicted spot on his first night of looking.', f: 'Galileo had seen Neptune in 1612 but thought it was a star.', p: ['planet', { color: '#3f6fd8', r: 30 }], x: ['uranus', 'voyager'] },
    { id: 'tsiolkovsky', n: 'Tsiolkovsky’s rocket equation', c: 'rocket', y: 1903, d: '1903', r: 'Russia', w: 'Konstantin Tsiolkovsky', s: 'A schoolteacher showed mathematically that rockets could reach space, and that multi-stage rockets would be needed.', how: 'His equation links a rocket’s speed to its exhaust speed and how much of it is fuel.', impact: 'He inspired the Soviet space programme.', f: 'He wrote: “Earth is the cradle of humanity, but one cannot live in the cradle forever.”', p: ['rocket', { stages: 3 }], x: ['goddard-rocket'] },
    { id: 'leavitt', n: 'Leavitt’s measuring stars', c: 'discovery', y: 1912, d: '1912', r: 'Harvard, USA', w: 'Henrietta Swan Leavitt', s: 'Leavitt found that certain pulsing stars (Cepheids) pulse slower the brighter they really are.', how: 'Comparing how bright one looks with how bright it really is gives its distance.', impact: 'It gave astronomers a ruler for the universe — Hubble used it to measure galaxies.', f: 'She worked as a “computer”, paid to measure photographic plates.', p: ['galaxy'], x: ['other-galaxies'] },
    { id: 'relativity', n: 'General relativity', c: 'discovery', y: 1915, d: '1915', r: 'Germany', w: 'Albert Einstein', s: 'Gravity is the bending of space and time by mass.', how: 'Massive objects curve space-time; light and planets follow the curves.', impact: 'Confirmed in 1919 when starlight bent around the Sun during an eclipse. GPS needs it to work.', f: 'Einstein’s theory predicted gravitational waves and black holes.', p: ['blackhole'], x: ['gravitational-waves', 'black-hole-image'] },
    { id: 'payne', n: 'Stars are made mostly of hydrogen', c: 'discovery', y: 1925, d: '1925', r: 'Harvard, USA', w: 'Cecilia Payne-Gaposchkin', s: 'Payne showed that stars are made almost entirely of hydrogen and helium, unlike the Earth.', how: 'She worked out what the lines in star spectra meant at stars’ high temperatures.', impact: 'Called the most brilliant PhD thesis in astronomy; senior astronomers first told her she must be wrong.', f: 'She later became the first woman to head a department at Harvard.', p: ['sun'], x: ['spectroscopy'] },
    { id: 'goddard-rocket', n: 'First liquid-fuel rocket', c: 'rocket', y: 1926, d: '1926', r: 'Massachusetts, USA', w: 'Robert Goddard', s: 'Goddard launched the first rocket powered by liquid fuel — the kind that later reached space.', how: 'Petrol and liquid oxygen burned in a chamber and blasted out of a nozzle.', impact: 'It flew 12 metres high for 2.5 seconds, but it started the age of modern rockets.', f: 'The New York Times mocked him in 1920; it published a correction in 1969 as Apollo 11 flew.', p: ['rocket', { stages: 1, color: '#d9dee2' }], x: ['tsiolkovsky', 'v2-space', ['weapons-atlas.html#fire-arrow', 'The first rockets']] },
    { id: 'other-galaxies', n: 'Other galaxies', c: 'discovery', y: 1924, d: '1924', r: 'California, USA', w: 'Edwin Hubble', s: 'Hubble proved that the Andromeda “nebula” is a separate galaxy far outside the Milky Way.', how: 'He found Cepheid stars in Andromeda and used Leavitt’s rule to measure its distance.', impact: 'The universe suddenly contained billions of galaxies.', f: 'Before 1924 many astronomers thought the Milky Way was the whole universe.', p: ['galaxy'], x: ['leavitt', 'expanding-universe', 'al-sufi'] },
    { id: 'expanding-universe', n: 'The expanding universe', c: 'discovery', y: 1929, d: '1927–1929', r: 'Belgium and USA', w: 'Georges Lemaître; Edwin Hubble', s: 'The farther away a galaxy is, the faster it moves away: the universe is expanding.', how: 'Light from distant galaxies is stretched to redder colours (redshift).', impact: 'It led to the Big Bang theory: the universe began about 13.8 billion years ago.', f: 'Lemaître, a Catholic priest, called the beginning the “primeval atom”.', p: ['bigbang'], x: ['other-galaxies', 'cmb', 'dark-energy'] },
    { id: 'pluto', n: 'Discovery of Pluto', c: 'discovery', y: 1930, d: '1930', r: 'Arizona, USA', w: 'Clyde Tombaugh', s: 'A 24-year-old found Pluto by comparing photographs of the sky taken days apart.', how: 'A blink comparator switched between two photos so a moving dot stood out.', impact: 'In 2006 astronomers reclassified Pluto as a dwarf planet.', f: 'An 11-year-old girl, Venetia Burney, suggested the name Pluto.', p: ['planet', { color: '#c9b49a', r: 22 }], x: ['pluto-dwarf', 'new-horizons'] },
    { id: 'radio-astronomy', n: 'Radio astronomy', c: 'scope', y: 1932, d: '1932', r: 'New Jersey, USA', w: 'Karl Jansky', s: 'Jansky found radio waves coming from the centre of the Milky Way while studying telephone static.', how: 'A rotating antenna picked up a hiss that rose and fell with the stars.', impact: 'Radio telescopes later discovered pulsars, quasars and the afterglow of the Big Bang.', f: 'The unit of radio brightness is called the jansky.', p: ['telescope', { type: 'radio' }], x: ['cmb', 'pulsars'] },
    { id: 'v2-space', n: 'V-2: first object in space', c: 'rocket', y: 1944, d: '1944', r: 'Germany', w: 'Wernher von Braun and team', s: 'A V-2 missile test flight in June 1944 became the first human-made object to cross into space.', how: 'A liquid-fuel rocket engine pushed it more than 100 km high.', impact: 'Built as a weapon by forced labour, it became the starting point for both the US and Soviet space programmes.', f: 'A US-launched V-2 took the first photo of Earth from space in 1946.', p: ['missile', { type: 'v2' }], x: ['goddard-rocket', 'sputnik-1', ['weapons-atlas.html#v2-rocket', 'The V-2 in the Weapons Atlas']] },
    // ---------------- space race
    { id: 'palomar', n: 'Hale Telescope (Palomar)', c: 'scope', y: 1948, d: '1948', r: 'California, USA', w: 'George Ellery Hale', s: 'A 5-metre mirror telescope, the world’s largest for decades.', how: 'A huge, slow-cooled glass mirror gathered faint light from distant galaxies.', impact: 'Used to discover quasars and study the universe’s expansion.', f: 'The glass mirror took 10 months to cool so it would not crack.', p: ['telescope', { type: 'observatory' }], x: ['keck', 'reflecting-telescope'] },
    { id: 'sputnik-1', n: 'Sputnik 1', c: 'sat', y: 1957, d: '4 October 1957', r: 'Soviet Union (Baikonur)', w: 'Sergei Korolev and the Soviet space programme', s: 'The first artificial satellite: a metal ball with four antennas that beeped as it circled Earth every 96 minutes.', how: 'An R-7 rocket threw it fast enough (about 8 km per second) to keep falling around the Earth.', impact: 'It started the space race and led the USA to create NASA in 1958.', f: 'Radio amateurs around the world tuned in to its “beep-beep”.', p: ['satellite', { type: 'sputnik' }], x: ['laika', 'explorer-1', ['weapons-atlas.html#icbm', 'The R-7 missile']] },
    { id: 'laika', n: 'Laika, the first animal in orbit', c: 'human', y: 1957, d: 'November 1957', r: 'Soviet Union', w: 'Soviet space programme', s: 'A stray dog from Moscow became the first animal to orbit the Earth, aboard Sputnik 2.', how: 'A small pressurised cabin carried her with food, water and sensors.', impact: 'She proved living things could survive launch, but she died within hours from heat. Animals helped make human flight safer.', f: 'Belka and Strelka orbited and returned safely in 1960.', p: ['capsule', { earth: 1 }], x: ['sputnik-1', 'gagarin'] },
    { id: 'explorer-1', n: 'Explorer 1 and the Van Allen belts', c: 'sat', y: 1958, d: '1958', r: 'USA', w: 'James Van Allen; Jet Propulsion Laboratory', s: 'America’s first satellite discovered belts of radiation trapped by Earth’s magnetic field.', how: 'A Geiger counter on board measured charged particles.', impact: 'The first big scientific discovery of the space age.', f: 'Its instruments were built by a team led by Van Allen at the University of Iowa.', p: ['satellite', { type: 'sputnik' }], x: ['sputnik-1', 'vanguard-1'] },
    { id: 'vanguard-1', n: 'Vanguard 1', c: 'sat', y: 1958, d: '1958', r: 'USA', w: 'US Naval Research Laboratory', s: 'A grapefruit-sized satellite, the first powered by solar cells — and the oldest human object still in orbit.', how: 'Solar cells powered its radio for six years.', impact: 'It proved solar power works in space and showed Earth is slightly pear-shaped.', f: 'It is expected to stay in orbit for about 200 more years.', p: ['satellite', { type: 'sputnik' }], x: ['explorer-1', ['invention-atlas.html#solar-cell', 'Solar cells']] },
    { id: 'luna-2', n: 'Luna 2: first craft to reach the Moon', c: 'moon', y: 1959, d: '1959', r: 'Soviet Union', w: 'Soviet space programme', s: 'The first human-made object to touch another world, crashing onto the Moon on purpose.', how: 'It was aimed so accurately that it hit the Moon after a day and a half.', impact: 'It showed the Moon has no strong magnetic field.', f: 'It carried metal pennants with the Soviet coat of arms.', p: ['moon'], x: ['luna-3', 'luna-9'] },
    { id: 'luna-3', n: 'Luna 3: the far side of the Moon', c: 'moon', y: 1959, d: '1959', r: 'Soviet Union', w: 'Soviet space programme', s: 'The first photos of the side of the Moon we never see from Earth.', how: 'It looped behind the Moon, took photos on film, developed them on board and scanned them for radio.', impact: 'The far side turned out to have very few dark “seas”.', f: 'Many far-side craters are named after Soviet scientists because of this mission.', p: ['moon', { far: 1 }], x: ['luna-2', 'change-4'] },
    { id: 'tiros-1', n: 'TIROS-1: first weather satellite', c: 'sat', y: 1960, d: '1960', r: 'USA', w: 'NASA', s: 'A satellite with TV cameras that sent back the first pictures of clouds from space.', how: 'It photographed weather systems as it orbited.', impact: 'Weather forecasting changed forever; satellites now track every hurricane.', f: 'It worked for only 78 days but sent back about 23,000 pictures.', p: ['satellite'], x: ['landsat'] },
    { id: 'gagarin', n: 'Yuri Gagarin: first person in space', c: 'human', y: 1961, d: '12 April 1961', r: 'Soviet Union', w: 'Yuri Gagarin; Sergei Korolev', s: 'Gagarin orbited the Earth once in Vostok 1, in 108 minutes.', how: 'The capsule flew automatically; he ejected near the ground and landed by parachute.', impact: 'He became a world hero. Weeks later, Alan Shepard became the first American in space.', f: 'At launch he said “Poyekhali!” — “Let’s go!”', p: ['capsule', { earth: 1, color: '#c9b49a' }], x: ['laika', 'tereshkova', 'apollo-11'] },
    { id: 'telstar', n: 'Telstar', c: 'sat', y: 1962, d: '1962', r: 'USA, UK and France', w: 'Bell Labs, NASA, the British and French post offices', s: 'The first satellite to relay live television across the Atlantic.', how: 'It received signals from one ground station and amplified them down to another.', impact: 'Satellites now carry TV, phone calls and internet worldwide.', f: 'A pop instrumental named “Telstar” was a number-one hit in 1962.', p: ['satellite'], x: ['starlink'] },
    { id: 'mariner-2', n: 'Mariner 2 at Venus', c: 'planet', y: 1962, d: '1962', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'The first successful flyby of another planet, finding Venus scorching hot.', how: 'It flew past Venus at about 35,000 km, measuring its temperature with instruments.', impact: 'Venus turned out to be about 460 °C at the surface — no jungles, as some had imagined.', f: 'A missing hyphen in software doomed Mariner 1 a month earlier.', p: ['planet', { color: '#e8c070' }], x: ['venera-7'] },
    { id: 'tereshkova', n: 'Valentina Tereshkova: first woman in space', c: 'human', y: 1963, d: '1963', r: 'Soviet Union', w: 'Valentina Tereshkova', s: 'A textile worker and parachutist, she orbited Earth 48 times in Vostok 6.', how: 'She spent almost three days alone in space.', impact: 'She was the only woman to fly solo in space. The next woman went 19 years later.', f: 'Her call sign was “Chaika” — seagull.', p: ['astronaut', { earth: 1 }], x: ['gagarin', 'sally-ride'] },
    { id: 'arecibo', n: 'Arecibo radio telescope', c: 'scope', y: 1963, d: '1963', r: 'Puerto Rico', w: 'Cornell University; William Gordon', s: 'A 305-metre dish built in a natural sinkhole, the world’s largest for over 50 years.', how: 'The fixed dish focused radio waves onto receivers hanging above it.', impact: 'It found the first binary pulsar and the first planets around another star (pulsar planets, 1992). It collapsed in 2020.', f: 'In 1974 it beamed a message towards a star cluster 25,000 light years away.', p: ['telescope', { type: 'radio' }], x: ['radio-astronomy', 'exoplanets'] },
    { id: 'leonov', n: 'First spacewalk', c: 'human', y: 1965, d: '1965', r: 'Soviet Union', w: 'Alexei Leonov', s: 'Leonov left his capsule and floated in space for 12 minutes, tied by a tether.', how: 'He used an inflatable airlock to get out of Voskhod 2.', impact: 'His suit swelled up and he had to let air out to squeeze back in.', f: 'Leonov later commanded the Soviet side of the Apollo–Soyuz mission.', p: ['astronaut', { tether: 1, earth: 1 }], x: ['gagarin', 'apollo-soyuz'] },
    { id: 'mariner-4', n: 'Mariner 4 at Mars', c: 'planet', y: 1965, d: '1965', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'The first close-up photos of another planet showed a cratered, Moon-like Mars.', how: 'It flew past Mars and sent 21 pictures, each taking hours to transmit.', impact: 'It ended hopes of canals and cities on Mars.', f: 'Engineers coloured the first image by hand from the numbers while waiting for the computer.', p: ['planet', { color: '#c96a3a', craters: 1 }], x: ['viking-1', 'mars-rovers'] },
    { id: 'cmb', n: 'Afterglow of the Big Bang', c: 'discovery', y: 1965, d: '1965', r: 'New Jersey, USA', w: 'Arno Penzias and Robert Wilson', s: 'A faint glow of microwaves from every direction — light left over from the early universe.', how: 'A sensitive antenna picked up a hiss that would not go away, even after cleaning out pigeon droppings.', impact: 'It was strong evidence for the Big Bang. Nobel Prize 1978.', f: 'Some of the static on an old analogue TV came from this cosmic background.', p: ['bigbang'], x: ['expanding-universe', 'radio-astronomy'] },
    { id: 'luna-9', n: 'Luna 9: first soft landing on the Moon', c: 'moon', y: 1966, d: '1966', r: 'Soviet Union', w: 'Soviet space programme', s: 'The first spacecraft to land gently on another world and send back photos from the surface.', how: 'An airbag-cushioned capsule bounced to a stop and opened its petals.', impact: 'It proved the Moon’s surface was firm enough for landers — not deep dust.', f: 'British astronomers at Jodrell Bank decoded and published its pictures before the Soviets did.', p: ['lander', { earth: 1 }], x: ['luna-2', 'apollo-11'] },
    { id: 'saturn-v', n: 'Saturn V', c: 'rocket', y: 1967, d: '1967', r: 'USA', w: 'NASA, led by Wernher von Braun', s: 'The 111-metre rocket that sent astronauts to the Moon — the most powerful rocket flown until 2022.', how: 'Three stages burned one after another, dropping away when empty.', impact: 'It launched every Apollo Moon mission and the Skylab station.', f: 'At lift-off it burned about 13 tonnes of fuel a second.', p: ['rocket', { stages: 3, tall: 1, fin: '#2d3741' }], x: ['apollo-11', 'artemis-1', 'starship'] },
    { id: 'pulsars', n: 'Pulsars', c: 'discovery', y: 1967, d: '1967', r: 'Cambridge, UK', w: 'Jocelyn Bell Burnell', s: 'A PhD student found radio pulses arriving every 1.3 seconds — from a spinning neutron star.', how: 'Neutron stars beam radio waves from their poles, sweeping past Earth like a lighthouse.', impact: 'Her supervisor shared the 1974 Nobel Prize; she did not. She later gave her 3-million-dollar prize money to help students.', f: 'At first the signal was jokingly labelled LGM-1, for “Little Green Men”.', p: ['pulsar'], x: ['supernova-1054', 'radio-astronomy'] },
    { id: 'apollo-8', n: 'Apollo 8 and Earthrise', c: 'human', y: 1968, d: 'December 1968', r: 'USA', w: 'Frank Borman, Jim Lovell and Bill Anders', s: 'The first people to leave Earth’s orbit, circle the Moon and see the whole Earth from far away.', how: 'A Saturn V sent them on a path that looped around the Moon 10 times.', impact: 'Anders’s photo “Earthrise” helped inspire the environmental movement.', f: 'They read from the Book of Genesis on Christmas Eve to a huge TV audience.', p: ['earth'], x: ['apollo-11', 'saturn-v'] },
    { id: 'apollo-11', n: 'Apollo 11: people on the Moon', c: 'moon', y: 1969, d: '20 July 1969', r: 'USA', w: 'Neil Armstrong, Buzz Aldrin and Michael Collins', s: 'Armstrong and Aldrin landed on the Moon and walked on it while Collins orbited above.', how: 'The lunar module Eagle landed with seconds of fuel to spare after Armstrong steered around boulders.', impact: 'About 600 million people watched. Twelve people walked on the Moon between 1969 and 1972.', f: 'Armstrong said: “That’s one small step for [a] man, one giant leap for mankind.”', p: ['lander', { flag: 1, earth: 1 }], x: ['saturn-v', 'apollo-13', 'artemis-1'] },
    { id: 'apollo-13', n: 'Apollo 13', c: 'human', y: 1970, d: '1970', r: 'USA', w: 'Jim Lovell, Jack Swigert and Fred Haise', s: 'An oxygen tank exploded on the way to the Moon; the crew used the lunar module as a lifeboat and returned safely.', how: 'Engineers on the ground invented fixes, like a way to fit square air filters into round holes.', impact: 'Called a “successful failure” — a triumph of teamwork.', f: '“Houston, we’ve had a problem” is often misquoted as “we have a problem”.', p: ['capsule', { chute: 1 }], x: ['apollo-11'] },
    { id: 'venera-7', n: 'Venera 7: landing on Venus', c: 'planet', y: 1970, d: '1970', r: 'Soviet Union', w: 'Soviet space programme', s: 'The first spacecraft to land on another planet and send data from its surface.', how: 'A tough capsule survived crushing pressure and heat for 23 minutes.', impact: 'Later Venera landers sent the only photos from Venus’s surface.', f: 'Venus’s surface pressure is like being 900 metres under the sea.', p: ['planet', { color: '#e8c070' }], x: ['mariner-2'] },
    { id: 'lunokhod', n: 'Lunokhod 1: first rover', c: 'moon', y: 1970, d: '1970', r: 'Soviet Union', w: 'Soviet space programme', s: 'The first robot rover on another world, driven by a team on Earth for over 10 months.', how: 'Drivers steered it using TV pictures that arrived with a delay of several seconds.', impact: 'It travelled about 10 km and took over 20,000 pictures.', f: 'Its laser reflector is still used to measure the Moon’s distance.', p: ['rover', { sky: '#0b1b2e' }], x: ['luna-9', 'mars-rovers'] },
    { id: 'dong-fang-hong', n: 'Dong Fang Hong 1: China’s first satellite', c: 'sat', y: 1970, d: '1970', r: 'China', w: 'Qian Xuesen and the Chinese space programme', s: 'China’s first satellite played the song “The East Is Red” from orbit.', how: 'A Long March 1 rocket put it into orbit.', impact: 'China became the fifth country to launch its own satellite (Japan was fourth, months earlier).', f: 'It is still in orbit.', p: ['satellite', { type: 'sputnik' }], x: ['yang-liwei', 'change-4'] },
    { id: 'salyut-1', n: 'Salyut 1: first space station', c: 'station', y: 1971, d: '1971', r: 'Soviet Union', w: 'Soviet space programme', s: 'The first space station, where three cosmonauts lived for 23 days.', how: 'A long module with living space, science instruments and docking for Soyuz.', impact: 'Tragically, the crew died on return when their capsule lost air. Later Salyuts were safer.', f: 'Cosmonauts now wear pressure suits during launch and landing because of this accident.', p: ['station', { type: 'skylab' }], x: ['skylab', 'mir'] },
    { id: 'pioneer-10', n: 'Pioneer 10', c: 'planet', y: 1972, d: '1972', r: 'USA', w: 'NASA Ames Research Center', s: 'The first spacecraft to cross the asteroid belt and fly past Jupiter.', how: 'Nuclear batteries powered it far from the Sun.', impact: 'It showed the asteroid belt could be crossed safely.', f: 'It carries a plaque with a drawing of a man and woman and a map to the Sun.', p: ['probe', { planet: '#d9a46a' }], x: ['voyager'] },
    { id: 'landsat', n: 'Landsat', c: 'sat', y: 1972, d: '1972', r: 'USA', w: 'NASA and the US Geological Survey; Virginia Norwood (scanner)', s: 'Satellites that have photographed all of Earth’s land since 1972.', how: 'Scanners record visible and invisible light to show crops, forests, cities and ice.', impact: 'The longest record of how Earth’s surface is changing.', f: 'Virginia Norwood, who designed its scanner, is called “the mother of Landsat”.', p: ['satellite'], x: ['tiros-1'] },
    { id: 'skylab', n: 'Skylab', c: 'station', y: 1973, d: '1973', r: 'USA', w: 'NASA', s: 'America’s first space station, made from a leftover Saturn V rocket stage.', how: 'Three crews lived aboard, studying the Sun and how the body copes with long spaceflight.', impact: 'The first crew repaired damage from launch with a parasol sunshade.', f: 'It fell back to Earth in 1979, scattering debris over Western Australia.', p: ['station', { type: 'skylab' }], x: ['salyut-1', 'iss'] },
    { id: 'apollo-soyuz', n: 'Apollo–Soyuz handshake', c: 'human', y: 1975, d: '1975', r: 'USA and Soviet Union', w: 'Thomas Stafford, Alexei Leonov and crews', s: 'American and Soviet spacecraft docked and the crews shook hands in orbit — a symbol of easing Cold War tension.', how: 'A special docking module linked the two different spacecraft.', impact: 'It paved the way for later cooperation on Mir and the ISS.', f: 'The crews learned each other’s languages for the mission.', p: ['station', { type: 'ring' }], x: ['iss', 'leonov'] },
    { id: 'viking-1', n: 'Viking 1 lands on Mars', c: 'planet', y: 1976, d: '1976', r: 'USA', w: 'NASA', s: 'The first successful working lander on Mars, sending colour photos and testing the soil for life.', how: 'Robotic arms scooped soil into an on-board laboratory.', impact: 'The life tests were inconclusive; it worked for over six years.', f: 'A Viking orbiter photo of a hill that looked like a face became famous.', p: ['rover'], x: ['mariner-4', 'mars-rovers'] },
    // ---------------- 1977–1999
    { id: 'voyager', n: 'Voyager 1 and 2', c: 'planet', y: 1977, d: '1977', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'Twin probes that toured Jupiter, Saturn, Uranus and Neptune and are now in interstellar space.', how: 'A rare line-up of the planets let each one swing the probes on to the next (gravity assist).', impact: 'They found volcanoes on Io and geysers on Triton. Voyager 1 entered interstellar space in 2012.', f: 'Each carries a Golden Record with sounds and music of Earth.', p: ['probe', { record: 1, planet: '#d9a46a' }], x: ['pioneer-10', 'neptune', 'new-horizons'] },
    { id: 'gps', n: 'GPS satellites', c: 'sat', y: 1978, d: '1978 (first); 1995 (complete)', r: 'USA', w: 'US Department of Defense', s: 'A network of about 31 satellites that lets any receiver find its exact position.', how: 'Each satellite broadcasts its position and the time; the receiver works out its distance from several.', impact: 'Navigation on phones, ships, aircraft, farming and timing for banks and the internet.', f: 'Europe (Galileo), Russia (GLONASS), China (BeiDou) and others run their own systems.', p: ['satellite', { type: 'cluster' }], x: ['starlink', ['invention-atlas.html#gps-navigation', 'GPS navigation']] },
    { id: 'ariane', n: 'Ariane rockets', c: 'rocket', y: 1979, d: '1979', r: 'Europe (launched from French Guiana)', w: 'European Space Agency', s: 'Europe’s own rockets, launching satellites for countries and companies around the world.', how: 'Launched near the equator, where Earth’s spin gives rockets an extra push.', impact: 'Ariane 5 launched the James Webb Space Telescope in 2021.', f: 'Ariane 5 flight 501 in 1996 failed because of a software number overflow.', p: ['rocket', { boosters: 1, stages: 2 }], x: ['jwst'] },
    { id: 'space-shuttle', n: 'Space Shuttle', c: 'human', y: 1981, d: '1981 – 2011', r: 'USA', w: 'NASA', s: 'A reusable spaceplane that launched like a rocket and landed like a glider, flying 135 missions.', how: 'Two solid boosters and three main engines fed by a big orange tank lifted the orbiter.', impact: 'It launched Hubble and built the ISS. Two shuttles, Challenger and Columbia, were lost with their crews.', f: 'The orbiter was covered in about 24,000 heat-resistant tiles.', p: ['shuttle'], x: ['challenger', 'hubble-telescope', 'iss'] },
    { id: 'sally-ride', n: 'Sally Ride', c: 'human', y: 1983, d: '1983', r: 'USA', w: 'Sally Ride', s: 'The first American woman in space, a physicist who flew on the Space Shuttle Challenger.', how: 'She operated the shuttle’s robotic arm to release and catch a satellite.', impact: 'She later founded a company to inspire girls in science.', f: 'Reporters asked her if spaceflight would affect her “reproductive organs” and whether she cried at work.', p: ['astronaut'], x: ['tereshkova', 'space-shuttle'] },
    { id: 'challenger', n: 'Challenger disaster', c: 'human', y: 1986, d: '28 January 1986', r: 'USA', w: 'Crew including teacher Christa McAuliffe', s: 'The Space Shuttle Challenger broke apart 73 seconds after launch, killing all seven crew.', how: 'Cold weather stiffened a rubber O-ring seal in a booster, letting hot gas escape.', impact: 'Engineers had warned about the cold; the disaster changed how NASA handles safety warnings.', f: 'Physicist Richard Feynman showed the problem by dipping an O-ring in iced water at a hearing.', p: ['shuttle'], x: ['space-shuttle', 'columbia'] },
    { id: 'mir', n: 'Mir space station', c: 'station', y: 1986, d: '1986 – 2001', r: 'Soviet Union / Russia', w: 'Soviet and Russian space programme', s: 'The first modular space station, built piece by piece and lived in for nearly 10 years without a break.', how: 'Modules launched separately docked together in orbit.', impact: 'Valeri Polyakov spent a record 437 days aboard. Americans visited in the 1990s.', f: 'Mir survived a fire and a collision with a supply ship in 1997.', p: ['station'], x: ['salyut-1', 'iss'] },
    { id: 'giotto', n: 'Giotto meets Halley’s Comet', c: 'planet', y: 1986, d: '1986', r: 'Europe', w: 'European Space Agency', s: 'The first close-up images of a comet’s nucleus — a dark, potato-shaped lump of ice and dust.', how: 'It flew within 600 km of the nucleus, protected by a dust shield.', impact: 'The nucleus was much darker than expected, like coal.', f: 'It is named after the painter Giotto, who painted the comet of 1301 as the Star of Bethlehem.', p: ['comet'], x: ['halley', 'rosetta'] },
    { id: 'hubble-telescope', n: 'Hubble Space Telescope', c: 'scope', y: 1990, d: '1990', r: 'USA and Europe', w: 'NASA and ESA', s: 'A telescope in orbit above the blurring atmosphere, which has taken some of the most famous pictures in science.', how: 'A 2.4-metre mirror and cameras orbiting about 540 km up.', impact: 'Its mirror was slightly wrong; astronauts fixed it in 1993. It helped measure the age of the universe and discover dark energy.', f: 'Its Hubble Deep Field photo found about 3,000 galaxies in a tiny dark patch of sky.', p: ['telescope', { type: 'space' }], x: ['jwst', 'space-shuttle', 'dark-energy'] },
    { id: 'keck', n: 'Keck telescopes', c: 'scope', y: 1993, d: '1993', r: 'Hawaii, USA', w: 'W. M. Keck Observatory', s: 'Twin 10-metre telescopes with mirrors made of 36 hexagonal segments.', how: 'Computers keep the segments aligned to a tiny fraction of a hair’s width.', impact: 'Segmented mirrors made giant telescopes possible; Webb uses the same idea.', f: 'Andrea Ghez used Keck to prove a giant black hole sits at the centre of our galaxy (Nobel Prize 2020).', p: ['telescope', { type: 'observatory' }], x: ['palomar', 'jwst', 'black-hole-image'] },
    { id: 'shoemaker-levy', n: 'Comet hits Jupiter', c: 'discovery', y: 1994, d: '1994', r: 'Jupiter', w: 'Discovered by Carolyn and Eugene Shoemaker and David Levy', s: 'Pieces of comet Shoemaker–Levy 9 smashed into Jupiter, leaving dark scars bigger than Earth.', how: 'Jupiter’s gravity had torn the comet into about 21 pieces.', impact: 'It showed the danger of impacts and boosted efforts to track asteroids near Earth.', f: 'Carolyn Shoemaker discovered 32 comets.', p: ['planet', { color: '#d9a46a', bands: 1, spot: 1 }], x: ['dart'] },
    { id: 'galileo-probe', n: 'Galileo at Jupiter', c: 'planet', y: 1995, d: '1995', r: 'USA', w: 'NASA', s: 'The first spacecraft to orbit Jupiter and drop a probe into its atmosphere.', how: 'It orbited for eight years, studying the planet and its moons.', impact: 'It found evidence of a salty ocean under the ice of Europa.', f: 'It was crashed into Jupiter in 2003 so it would never contaminate Europa.', p: ['planet', { color: '#d9a46a', bands: 1, spot: 1, moon: 1 }], x: ['juno', 'europa-clipper'] },
    { id: 'exoplanets', n: 'Planets around other stars', c: 'discovery', y: 1995, d: '1995', r: 'Switzerland', w: 'Michel Mayor and Didier Queloz', s: 'The first planet found circling a Sun-like star, 51 Pegasi b — a giant hotter than any planet in our Solar System.', how: 'The planet’s pull made its star wobble, shifting the star’s light slightly.', impact: 'Over 5,000 exoplanets are now known. Nobel Prize 2019.', f: 'The first exoplanets of all were found around a pulsar in 1992.', p: ['exoplanet'], x: ['kepler-mission', 'jwst'] },
    { id: 'sojourner', n: 'Sojourner, first Mars rover', c: 'planet', y: 1997, d: '1997', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'A microwave-sized rover that bounced onto Mars inside airbags with the Pathfinder lander.', how: 'It drove slowly from rock to rock, measuring what they were made of.', impact: 'It proved cheap missions could work and led to bigger rovers.', f: 'It was named after Sojourner Truth, an anti-slavery and women’s rights campaigner.', p: ['rover'], x: ['mars-rovers', 'viking-1'] },
    { id: 'cassini', n: 'Cassini–Huygens at Saturn', c: 'planet', y: 1997, d: '1997 (launch); 2004 (arrival)', r: 'USA, Europe and Italy', w: 'NASA, ESA and the Italian Space Agency', s: 'A spacecraft that orbited Saturn for 13 years, and dropped the Huygens probe onto its moon Titan.', how: 'Huygens parachuted through Titan’s thick haze in 2005 — the farthest landing ever.', impact: 'It found geysers on Enceladus and lakes of liquid methane on Titan.', f: 'Cassini ended by diving into Saturn in 2017.', p: ['planet', { color: '#e3c78a', ring: 1 }], x: ['voyager', 'europa-clipper'] },
    { id: 'dark-energy', n: 'Dark energy', c: 'discovery', y: 1998, d: '1998', r: 'USA and Australia', w: 'Saul Perlmutter, Brian Schmidt and Adam Riess', s: 'Distant exploding stars showed that the universe’s expansion is speeding up.', how: 'Type Ia supernovae have a known brightness, so they show distance.', impact: 'Something unknown — called dark energy — makes up about 68% of the universe. Nobel Prize 2011.', f: 'The teams expected to find the expansion slowing down.', p: ['bigbang'], x: ['expanding-universe', 'hubble-telescope'] },
    { id: 'iss', n: 'International Space Station', c: 'station', y: 1998, d: '1998', r: 'USA, Russia, Europe, Japan and Canada', w: 'Five space agencies', s: 'The biggest structure ever built in space, lived in continuously since November 2000.', how: 'Modules and solar arrays were added over 40 assembly flights.', impact: 'Over 270 people from about 20 countries have visited.', f: 'It orbits Earth about every 90 minutes; crews see 16 sunrises a day.', p: ['station'], x: ['mir', 'tiangong', 'crew-dragon'] },
    // ---------------- new space age
    { id: 'columbia', n: 'Columbia disaster', c: 'human', y: 2003, d: '1 February 2003', r: 'USA', w: 'Crew including Kalpana Chawla and Ilan Ramon', s: 'The Space Shuttle Columbia broke apart as it came back to Earth, killing its seven crew.', how: 'Foam from the tank had struck the wing at launch, damaging the heat shield.', impact: 'It led to the end of the shuttle programme in 2011.', f: 'Kalpana Chawla was the first woman of Indian origin in space.', p: ['shuttle'], x: ['challenger', 'space-shuttle'] },
    { id: 'yang-liwei', n: 'Yang Liwei: China’s first astronaut', c: 'human', y: 2003, d: '2003', r: 'China', w: 'Yang Liwei', s: 'China became the third country to send a person into space on its own, aboard Shenzhou 5.', how: 'A Long March rocket launched the Shenzhou capsule, similar in design to Soyuz.', impact: 'China went on to build its own space station.', f: 'Chinese astronauts are often called taikonauts.', p: ['capsule', { earth: 1 }], x: ['tiangong', 'dong-fang-hong'] },
    { id: 'spaceshipone', n: 'SpaceShipOne', c: 'human', y: 2004, d: '2004', r: 'USA', w: 'Burt Rutan and Scaled Composites; funded by Paul Allen', s: 'The first privately built crewed spacecraft to reach space.', how: 'A carrier plane dropped it high up; a rocket then took it above 100 km.', impact: 'It won the 10-million-dollar Ansari X Prize and helped start space tourism.', f: 'It now hangs in the Smithsonian museum next to the Spirit of St. Louis.', p: ['shuttle'], x: ['crew-dragon'] },
    { id: 'mars-rovers', n: 'Spirit and Opportunity', c: 'planet', y: 2004, d: '2004', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'Twin rovers that found clear signs that liquid water once flowed on Mars.', how: 'Solar-powered rovers with cameras, drills and instruments to study rocks.', impact: 'Planned to last 90 days, Opportunity worked for over 14 years.', f: 'Opportunity’s last message, sent during a dust storm, was poetically translated as “my battery is low and it’s getting dark”.', p: ['rover'], x: ['sojourner', 'curiosity', 'perseverance'] },
    { id: 'pluto-dwarf', n: 'Pluto becomes a dwarf planet', c: 'discovery', y: 2006, d: '2006', r: 'Prague', w: 'International Astronomical Union', s: 'Astronomers defined “planet” and reclassified Pluto as a dwarf planet.', how: 'A planet must clear its orbit of other objects; Pluto shares its zone with many icy worlds.', impact: 'There are now eight planets, plus dwarf planets like Pluto, Eris and Ceres.', f: 'Finding Eris, similar in size to Pluto, in 2005 started the debate.', p: ['planet', { color: '#c9b49a', r: 20 }], x: ['pluto', 'new-horizons'] },
    { id: 'kepler-mission', n: 'Kepler space telescope', c: 'scope', y: 2009, d: '2009', r: 'USA', w: 'NASA; William Borucki', s: 'A telescope that stared at one patch of sky, finding thousands of planets by the tiny dips in starlight as they passed in front.', how: 'When a planet crosses its star, the star dims very slightly.', impact: 'It found over 2,600 planets and showed that planets are common.', f: 'Borucki’s idea was rejected several times before it was approved.', p: ['exoplanet'], x: ['exoplanets', 'jwst'] },
    { id: 'hayabusa', n: 'Hayabusa: asteroid samples', c: 'planet', y: 2010, d: '2010', r: 'Japan', w: 'JAXA', s: 'The first mission to bring back pieces of an asteroid to Earth.', how: 'It touched down on asteroid Itokawa and collected tiny dust grains.', impact: 'Hayabusa2 (2020) brought back more from asteroid Ryugu.', f: 'Despite broken engines and lost contact, the team nursed it home.', p: ['probe'], x: ['osiris-rex', 'rosetta'] },
    { id: 'messenger', n: 'MESSENGER at Mercury', c: 'planet', y: 2011, d: '2011', r: 'USA', w: 'NASA and Johns Hopkins APL', s: 'The first spacecraft to orbit Mercury, the planet closest to the Sun.', how: 'A sunshade protected it from heat; flybys of Earth, Venus and Mercury slowed it down.', impact: 'It found water ice in permanently shadowed craters near Mercury’s poles.', f: 'It is harder to get to Mercury than to Pluto in terms of fuel.', p: ['planet', { color: '#a09a90', craters: 1 }], x: ['parker'] },
    { id: 'curiosity', n: 'Curiosity rover', c: 'planet', y: 2012, d: '2012', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'A car-sized nuclear-powered rover that showed ancient Mars had lakes that could have supported life.', how: 'A rocket-powered “sky crane” lowered it to the ground on cables.', impact: 'Still exploring Mount Sharp more than a decade later.', f: 'It played “Happy Birthday” to itself on Mars in 2013.', p: ['rover'], x: ['mars-rovers', 'perseverance'] },
    { id: 'rosetta', n: 'Rosetta and Philae', c: 'planet', y: 2014, d: '2014', r: 'Europe', w: 'European Space Agency', s: 'The first spacecraft to orbit a comet and land a probe on it.', how: 'Rosetta chased comet 67P for 10 years; the Philae lander bounced and came to rest in a shadow.', impact: 'It found organic molecules on the comet.', f: 'Philae bounced about a kilometre high on its first touchdown.', p: ['comet'], x: ['giotto', 'hayabusa'] },
    { id: 'mangalyaan', n: 'Mangalyaan: India at Mars', c: 'planet', y: 2014, d: '2014', r: 'India', w: 'ISRO', s: 'India reached Mars orbit on its first attempt, for less than the budget of some space films.', how: 'It slowly raised its orbit around Earth before heading to Mars.', impact: 'India became the first Asian nation to reach Mars orbit.', f: 'The mission cost about 74 million dollars.', p: ['planet', { color: '#c96a3a' }], x: ['chandrayaan-3'] },
    { id: 'falcon-9-landing', n: 'Reusable rocket landing', c: 'rocket', y: 2015, d: '2015', r: 'USA', w: 'SpaceX', s: 'A Falcon 9 first stage landed upright after launching satellites — the start of reusable orbital rockets.', how: 'The booster flips around, relights its engines and lands on legs, steered by grid fins.', impact: 'Reusing boosters made launches much cheaper and more frequent.', f: 'Some boosters have flown more than 20 times.', p: ['rocket', { stages: 1, landing: 1 }], x: ['starship', 'crew-dragon'] },
    { id: 'new-horizons', n: 'New Horizons at Pluto', c: 'planet', y: 2015, d: '2015', r: 'USA', w: 'NASA and Johns Hopkins APL; Alan Stern', s: 'The first close-up view of Pluto, showing a heart-shaped plain of nitrogen ice and mountains of water ice.', how: 'It flew past at about 50,000 km/h after a nine-year journey.', impact: 'Pluto turned out to be geologically active.', f: 'It carries some of Clyde Tombaugh’s ashes.', p: ['planet', { color: '#d9c4a8', r: 30 }], x: ['pluto', 'voyager'] },
    { id: 'gravitational-waves', n: 'Gravitational waves detected', c: 'discovery', y: 2015, d: '2015', r: 'USA', w: 'LIGO team; Rainer Weiss, Kip Thorne and Barry Barish', s: 'Ripples in space-time from two black holes merging 1.3 billion years ago were detected on Earth.', how: 'Lasers in 4-km tunnels measured a stretch smaller than a thousandth of a proton’s width.', impact: 'A new way to “hear” the universe. Nobel Prize 2017.', f: 'Einstein predicted them in 1916 but thought they could never be measured.', p: ['waves'], x: ['relativity', 'black-hole-image'] },
    { id: 'juno', n: 'Juno at Jupiter', c: 'planet', y: 2016, d: '2016', r: 'USA', w: 'NASA', s: 'A solar-powered probe in a long looping orbit over Jupiter’s poles.', how: 'Three huge solar panels power it even far from the Sun.', impact: 'It revealed giant cyclones at Jupiter’s poles and its deep structure.', f: 'It carries three LEGO figures: Galileo, Jupiter and Juno.', p: ['planet', { color: '#d9a46a', bands: 1, spot: 1 }], x: ['galileo-probe'] },
    { id: 'parker', n: 'Parker Solar Probe', c: 'planet', y: 2018, d: '2018', r: 'USA', w: 'NASA; named after Eugene Parker', s: 'A probe that flies through the Sun’s outer atmosphere, closer than anything before.', how: 'An 11-cm carbon heat shield faces the Sun at over 1,000 °C.', impact: 'It is the fastest object ever made, at about 690,000 km/h.', f: 'Eugene Parker predicted the solar wind in 1958 and saw the probe launched at 91.', p: ['sun'], x: ['messenger'] },
    { id: 'change-4', n: 'Chang’e 4: landing on the far side', c: 'moon', y: 2019, d: '2019', r: 'China', w: 'China National Space Administration', s: 'The first soft landing on the far side of the Moon, with the Yutu-2 rover.', how: 'A relay satellite beyond the Moon passed messages to Earth.', impact: 'Chang’e 5 (2020) and Chang’e 6 (2024, from the far side) brought Moon samples home.', f: 'It carried cotton seeds that sprouted — the first plant to grow on the Moon.', p: ['lander', { earth: 0 }], x: ['luna-3', 'chandrayaan-3'] },
    { id: 'black-hole-image', n: 'First image of a black hole', c: 'discovery', y: 2019, d: '2019', r: 'Worldwide', w: 'Event Horizon Telescope team, including Katie Bouman', s: 'A picture of the glowing ring around the giant black hole in galaxy M87.', how: 'Radio telescopes across the Earth worked together as one Earth-sized telescope.', impact: 'In 2022 the team imaged Sagittarius A*, the black hole at our galaxy’s centre.', f: 'The data was too big to send over the internet, so hard drives were flown to one place.', p: ['blackhole'], x: ['relativity', 'gravitational-waves', 'keck'] },
    { id: 'starlink', n: 'Satellite megaconstellations', c: 'sat', y: 2019, d: '2019', r: 'USA and others', w: 'SpaceX (Starlink); OneWeb and others', s: 'Thousands of small satellites in low orbit providing internet almost anywhere on Earth.', how: 'Satellites pass signals between users, ground stations and each other with lasers.', impact: 'Internet for remote places — but astronomers worry about streaks in photos and space junk.', f: 'Several thousand satellites are already up — more than all earlier active satellites combined.', p: ['satellite', { type: 'cluster' }], x: ['telstar', 'gps'] },
    { id: 'crew-dragon', n: 'Crew Dragon', c: 'human', y: 2020, d: '2020', r: 'USA', w: 'SpaceX and NASA', s: 'The first commercially built spacecraft to carry astronauts to the International Space Station.', how: 'An automatic capsule with touchscreens docks with the ISS by itself.', impact: 'Crewed launches returned to the USA after nine years of relying on Soyuz.', f: 'In 2021 it flew the first all-civilian crew around Earth.', p: ['capsule'], x: ['iss', 'falcon-9-landing'] },
    { id: 'perseverance', n: 'Perseverance and Ingenuity', c: 'planet', y: 2021, d: '2021', r: 'USA', w: 'NASA Jet Propulsion Laboratory', s: 'A rover collecting rock samples in an ancient lake, and Ingenuity, the first aircraft to fly on another planet.', how: 'Ingenuity’s blades spun about 2,400 times a minute to fly in Mars’s thin air.', impact: 'Ingenuity flew 72 times. Perseverance stores samples for a future return mission.', f: 'Ingenuity carried a tiny piece of fabric from the Wright brothers’ first plane.', p: ['rover', { heli: 1 }], x: ['curiosity', 'tianwen-1', ['invention-atlas.html#airplane', 'The first aeroplane']] },
    { id: 'tianwen-1', n: 'Tianwen-1 and Zhurong', c: 'planet', y: 2021, d: '2021', r: 'China', w: 'China National Space Administration', s: 'China’s first Mars mission put an orbiter, a lander and the Zhurong rover on Mars at once.', how: 'The orbiter studied the planet before releasing the lander.', impact: 'China became the second country to drive a rover on Mars.', f: 'Zhurong is named after a god of fire in Chinese mythology.', p: ['rover'], x: ['perseverance', 'mangalyaan'] },
    { id: 'tiangong', n: 'Tiangong space station', c: 'station', y: 2021, d: '2021', r: 'China', w: 'China Manned Space Agency', s: 'China’s own modular space station, permanently crewed since 2022.', how: 'Three modules launched separately and joined in orbit.', impact: 'It hosts experiments from China and other countries.', f: 'Tiangong means “Heavenly Palace”.', p: ['station'], x: ['iss', 'yang-liwei'] },
    { id: 'jwst', n: 'James Webb Space Telescope', c: 'scope', y: 2021, d: '25 December 2021', r: 'USA, Europe and Canada', w: 'NASA, ESA and CSA', s: 'The largest space telescope, seeing infrared light from the first galaxies and the air of distant planets.', how: 'A 6.5-metre gold-coated mirror of 18 segments sits behind a tennis-court-sized sunshield, far from Earth.', impact: 'It has found galaxies from just a few hundred million years after the Big Bang.', f: 'The mirror and sunshield had to unfold in space like origami.', p: ['telescope', { type: 'jwst' }], x: ['hubble-telescope', 'ariane', 'exoplanets'] },
    { id: 'dart', n: 'DART: moving an asteroid', c: 'planet', y: 2022, d: '2022', r: 'USA', w: 'NASA and Johns Hopkins APL', s: 'A spacecraft crashed into the small asteroid Dimorphos and changed its orbit — the first test of planetary defence.', how: 'At 22,000 km/h, the impact nudged Dimorphos’s orbit around its larger partner.', impact: 'Its orbit shortened by 32 minutes — far more than the minimum goal.', f: 'Europe’s Hera mission is going to study the crash site.', p: ['comet'], x: ['shoemaker-levy'] },
    { id: 'artemis-1', n: 'Artemis I', c: 'moon', y: 2022, d: '2022', r: 'USA, with Europe', w: 'NASA and ESA', s: 'An uncrewed test flight of the SLS rocket and Orion capsule around the Moon, preparing for people to return.', how: 'Orion flew farther than any human-rated capsule before, then returned through the atmosphere at 40,000 km/h.', impact: 'Artemis missions plan to land the first woman and first person of colour on the Moon.', f: 'Mannequins named Commander Moonikin Campos, Helga and Zohar flew in the seats.', p: ['rocket', { stages: 2, boosters: 1, tall: 1, color: '#e2a63b' }], x: ['apollo-11', 'saturn-v'] },
    { id: 'chandrayaan-3', n: 'Chandrayaan-3', c: 'moon', y: 2023, d: '23 August 2023', r: 'India', w: 'ISRO', s: 'India landed near the Moon’s south pole, the first soft landing in that region.', how: 'The Vikram lander released the small Pragyan rover, which studied the soil.', impact: 'India became the fourth country to soft-land on the Moon.', f: 'The landing day is now celebrated as India’s National Space Day.', p: ['lander'], x: ['mangalyaan', 'change-4'] },
    { id: 'osiris-rex', n: 'OSIRIS-REx', c: 'planet', y: 2023, d: '2023', r: 'USA', w: 'NASA and the University of Arizona', s: 'Brought back about 120 grams of rock and dust from the asteroid Bennu.', how: 'It touched Bennu for seconds, puffed gas to stir up material and caught it.', impact: 'The samples contain water-bearing minerals and building blocks of life.', f: 'Bennu’s surface was so loose that the probe nearly sank into it.', p: ['probe'], x: ['hayabusa'] },
    { id: 'starship', n: 'Starship', c: 'rocket', y: 2023, d: '2023 (first full flight)', r: 'USA', w: 'SpaceX', s: 'The biggest and most powerful rocket ever flown, designed to be fully reusable.', how: 'A 33-engine booster lifts a ship with its own engines; both are meant to land and fly again.', impact: 'NASA plans to use a version as a Moon lander for Artemis.', f: 'In 2024 the giant booster was caught by the launch tower’s arms.', p: ['rocket', { stages: 2, tall: 1, color: '#c9ced3', fin: '#9aa3a8' }], x: ['saturn-v', 'falcon-9-landing', 'artemis-1'] },
    { id: 'europa-clipper', n: 'Europa Clipper', c: 'planet', y: 2024, d: '2024 (launch)', r: 'USA', w: 'NASA', s: 'A spacecraft on its way to Jupiter’s moon Europa to study the ocean hidden under its ice.', how: 'It will fly past Europa about 50 times, scanning its ice and ocean.', impact: 'It will look for the ingredients that could support life.', f: 'It carries a poem by US Poet Laureate Ada Limón, engraved on a plate.', p: ['planet', { color: '#d9d0c0', craters: 0 }], x: ['galileo-probe', 'cassini'] }
  ];
})();
